-- Restore Theramore's Fall - Alliance (map 1000, scenario 71).
-- Spawn, addon, and text data were ported read-only from Legends of Azeroth
-- Pandaria 5.4.8 (build 18414), while scripts were adapted to Legion 7.3.5.
-- Legion build 26972 DB2 confirms six steps (193, 210, 175, 217, 185, 186),
-- their criteria trees, and Alliance LFG 566.
START TRANSACTION;

-- Replace any incomplete population and remove GUID-owned dependencies.
DELETE `ca` FROM `creature_addon` `ca`
INNER JOIN `creature` `c` ON `c`.`guid` = `ca`.`guid`
WHERE `c`.`map` = 1000;
DELETE `wp` FROM `waypoint_data` `wp`
INNER JOIN `creature` `c` ON `c`.`guid` = `wp`.`id`
WHERE `c`.`map` = 1000;
DELETE `cf` FROM `creature_formations` `cf`
INNER JOIN `creature` `c` ON `c`.`guid` = `cf`.`memberGUID`
WHERE `c`.`map` = 1000;
DELETE `cf` FROM `creature_formations` `cf`
INNER JOIN `creature` `c` ON `c`.`guid` = `cf`.`leaderGUID`
WHERE `c`.`map` = 1000;
DELETE `gec` FROM `game_event_creature` `gec`
INNER JOIN `creature` `c` ON `c`.`guid` = `gec`.`guid`
WHERE `c`.`map` = 1000;
DELETE `pc` FROM `pool_creature` `pc`
INNER JOIN `creature` `c` ON `c`.`guid` = `pc`.`guid`
WHERE `c`.`map` = 1000;
DELETE `geg` FROM `game_event_gameobject` `geg`
INNER JOIN `gameobject` `g` ON `g`.`guid` = `geg`.`guid`
WHERE `g`.`map` = 1000;
DELETE `pg` FROM `pool_gameobject` `pg`
INNER JOIN `gameobject` `g` ON `g`.`guid` = `pg`.`guid`
WHERE `g`.`map` = 1000;
DELETE FROM `creature` WHERE `map` = 1000;
DELETE FROM `gameobject` WHERE `map` = 1000;

